```json
{
  "root_causes": [
    {
      "service": "ts-ui-dashboard",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS p, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(min(duration)/1e6,1) AS min_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%order/refresh%' AND attr_span_kind='Server' UNION ALL SELECT 'norm', count(*), round(quantile_cont(duration,0.5)/1e6,1), round(min(duration)/1e6,1) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%order/refresh%' AND attr_span_kind='Server'",
          "claim": "Every abnormal ui-dashboard order/refresh request takes at least ~3000 ms (p50 3001 ms), versus p50 6 ms normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS p, service_name, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND span_name LIKE '%order/refresh%' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Only one order-service refresh span appears in the abnormal period, and it takes 7 ms, so most slow dashboard refreshes never reach order-service in time."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, time, round(duration/1e6,1) AS ms, attr_status_code FROM abnormal_traces WHERE trace_id='3c12ceddfcf63ca7f3865f36a5e6a843' AND attr_span_kind='Server' ORDER BY time",
          "claim": "In a 20 s refresh trace, order-service returns in 7 ms, but the ui-dashboard server span runs on for about 20 s after it."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%users/login%' GROUP BY 1",
          "claim": "Other ui-dashboard paths such as login stay at normal latency (p50 about 97 ms), so the delay is specific to the order/refresh path."
        }
      ]
    }
  ],
  "propagation": []
}
```

